package se.anders.tunerstudio.pidautotune.session;
/** Conservative comparison of consecutive manually-tuned DC-IAC capture sessions. */
public final class DcIacIterationComparisonEngine {public DcIacIterationComparison compare(DcIacTuningSessionSummary b,DcIacTuningSessionSummary c){if(b==null||c==null)return new DcIacIterationComparison(DcIacIterationComparison.INSUFFICIENT,0,0,0,0,"Two archived sessions are required for iteration comparison.");if(!b.getConfigurationName().equals(c.getConfigurationName()))return new DcIacIterationComparison(DcIacIterationComparison.NOT_COMPARABLE,b.getSequence(),c.getSequence(),0,0,"Sessions use different ECU configurations.");if(!finite(b.getCenterTarget())||!finite(c.getCenterTarget())||Math.abs(b.getCenterTarget()-c.getCenterTarget())>2.5)return new DcIacIterationComparison(DcIacIterationComparison.NOT_COMPARABLE,b.getSequence(),c.getSequence(),0,0,"Running-idle evidence centers differ by more than 2.5 position points; repeat the same local region for an attributable comparison.");int improved=0,regressed=0,comparable=0;int[]s;s=score(b.getMedianBiasCorrectionAbs(),c.getMedianBiasCorrectionAbs(),.50);improved+=s[0];regressed+=s[1];comparable+=s[2];s=score(b.getMedianOvershootAbs(),c.getMedianOvershootAbs(),5);improved+=s[0];regressed+=s[1];comparable+=s[2];s=score(b.getMedianSteadyErrorAbs(),c.getMedianSteadyErrorAbs(),.15);improved+=s[0];regressed+=s[1];comparable+=s[2];s=score(b.getMedianPeakDuty(),c.getMedianPeakDuty(),5);improved+=s[0];regressed+=s[1];comparable+=s[2];s=score(b.getMedianInitialIAbs(),c.getMedianInitialIAbs(),.50);improved+=s[0];regressed+=s[1];comparable+=s[2];if(comparable<2)return new DcIacIterationComparison(DcIacIterationComparison.INSUFFICIENT,b.getSequence(),c.getSequence(),improved,regressed,"Too few comparable running-idle metrics exist in the two sessions.");String status=improved>=2&&regressed==0?DcIacIterationComparison.IMPROVED:regressed>=2&&improved==0?DcIacIterationComparison.REGRESSED:improved>0&&regressed>0?DcIacIterationComparison.MIXED:DcIacIterationComparison.SIMILAR;return new DcIacIterationComparison(status,b.getSequence(),c.getSequence(),improved,regressed,"Compared "+comparable+" available running-idle metrics: "+improved+" materially improved, "+regressed+" materially regressed. Keep/revert remains manual.");}private static int[]score(double b,double c,double t){if(!finite(b)||!finite(c))return new int[]{0,0,0};double d=c-b;return d<=-t?new int[]{1,0,1}:d>=t?new int[]{0,1,1}:new int[]{0,0,1};}private static boolean finite(double v){return!Double.isNaN(v)&&!Double.isInfinite(v);}}
